-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Armas de Genshin Impact: 246. Con stats, efecto por nivel, como
-- conseguirlas, materiales y personajes recomendados (guias de Game8).
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.
--
-- Estas armas no estaban en la copia de la base de datos (genshin_armas.sql no
-- llego a ejecutarse), asi que salen de los archivos: datos de Yatta y
-- recomendados de Game8.

--
-- PARTE 1 de 4 (67 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.weapons (
  id, game_id, name, name_en, rarity, category, image_url, description, base_hp, base_atk, base_def, sub_stat_name, sub_stat_value, passive_name, passive_levels, how_to_get, ascension, good_for, recommended
)
values
  ('gi-w-14408', 'genshin-impact', 'Ágata del Peñasco Oscuro', 'Blackcliff Agate', '4', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_Blackrock.png', 'Un misterioso catalizador hecho de piedra negra. Tiene un brillo carmesí siniestro que parece latir en sincronía con los temblores de las profundidades de la tierra.', null, 510, null, 'Daño CRIT', '55,1%', 'Victoria tras victoria', '["Al derrotar a un enemigo, aumenta el ATQ en un 12% durante 30 s, pudiéndose acumular hasta 3 veces. La duración de cada acumulación es independiente de las demás.","Al derrotar a un enemigo, aumenta el ATQ en un 15% durante 30 s, pudiéndose acumular hasta 3 veces. La duración de cada acumulación es independiente de las demás.","Al derrotar a un enemigo, aumenta el ATQ en un 18% durante 30 s, pudiéndose acumular hasta 3 veces. La duración de cada acumulación es independiente de las demás.","Al derrotar a un enemigo, aumenta el ATQ en un 21% durante 30 s, pudiéndose acumular hasta 3 veces. La duración de cada acumulación es independiente de las demás.","Al derrotar a un enemigo, aumenta el ATQ en un 24% durante 30 s, pudiéndose acumular hasta 3 veces. La duración de cada acumulación es independiente de las demás."]'::jsonb, 'Ofertas de Paimon: se compra con Brillo estelar sin dueño', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":2},{"nombre":"Daga de cacería","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112029.png","cantidad":3},{"nombre":"Arena brillante de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114013.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":8},{"nombre":"Daga de cacería","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112029.png","cantidad":12},{"nombre":"Piedra reluciente de Guyun","icono"